"""Order records."""


class Order:
    def __init__(self, customer, amount):
        self.customer = customer
        self.amount = amount

    def __repr__(self):
        return "Order(%r, %r)" % (self.customer, self.amount)


ROWS = [('birch', 45), ('acme', 5), ('acme', 34), ('birch', 50), ('corvo', 6), ('corvo', 22), ('acme', 3)]


def load_orders():
    """Yield the stored orders one at a time."""
    for customer, amount in ROWS:
        yield Order(customer, amount)


def feed_orders():
    """Endless feed of orders: repeats the stored rows for ever."""
    while True:
        for customer, amount in ROWS:
            yield Order(customer, amount)
